def _apply_outflow(self, concentration: np.ndarray) -> float:
    if not self._outflow_pores:
        return 0.0
    # The outflow is evaluated on the conduits adjacent to each declared
    # outflow pore: the conductive constitutive relation must use the
    # pore concentrations at that throat's own ends, not a stage-global
    # boundary-pair difference.
    throat_count = len(self.case.throat_connections)
    left_values = np.zeros(throat_count, dtype=float)
    right_values = np.zeros(throat_count, dtype=float)
    outflow_set = set(self._outflow_pores)
    throat_end: dict[int, tuple[int, int]] = {}
    for throat_index, (left, right) in enumerate(self.case.throat_connections):
        if left in outflow_set or right in outflow_set:
            left_values[throat_index] = float(concentration[left])
            right_values[throat_index] = float(concentration[right])
            throat_end[throat_index] = (left, right)
    if not throat_end:
        return 0.0
    pressure_drop = np.column_stack((left_values, right_values))
    flux = ad_dif_conductance(self._state.active_coefficients(), pressure_drop)
    # Report the flux on the conduit next to the first declared outflow
    # pore, consistent with the stage data supplied for that boundary.
    first_outflow = self._outflow_pores[0]
    for index in sorted(throat_end):
        if first_outflow in throat_end[index]:
            return float(flux[index])
    return float(flux[next(iter(throat_end))])

