def _apply_outflow(self, concentration: np.ndarray) -> float:
    if not self._outflow_pores:
        return 0.0
    # The outflow is evaluated on each conduit adjacent to a declared
    # outflow pore.  The conductive constitutive relation must use the
    # concentrations at that throat's own ends: applying the stage-global
    # boundary-pair drop to every conduit is a stage-data mismatch that
    # distorts the reported flux for the physical stage being simulated.
    outflow_set = set(self._outflow_pores)
    net_outflow = 0.0
    for throat_index, (left, right) in enumerate(self.case.throat_connections):
        if left not in outflow_set and right not in outflow_set:
            continue
        conductance = float(self._state.active_coefficients()[throat_index])
        # Net conductive current leaving the domain through this conduit.
        # A boundary pore is held fixed by the imposed value (see
        # _assemble_rhs), so the fixed condition itself does not carry
        # net current out of the domain.
        if left in outflow_set:
            net_outflow -= conductance * (
                float(concentration[left]) - float(concentration[right])
            )
        if right in outflow_set:
            net_outflow += conductance * (
                float(concentration[right]) - float(concentration[left])
            )
    return float(net_outflow)

